import sys

def next_smallest_palindrome(num):
    numstr = str(num)
    n = len(numstr)
    for i in range(num + 1, 10**n + 10**n):
        s = str(i)
        if len(s) == n or len(s) == n + 1:
            if s == s[::-1]:
                return i

